create function pg_temp.qa_execute(p_args jsonb,p_tool text default 'create_appointment') returns uuid language plpgsql as $$
declare v_id uuid; v_result uuid;
begin
 select id into v_id from public.create_assistant_pending_action_for_current_user(pg_temp.qid('north'),p_tool,p_args,now()+interval '5 minutes');
 perform public.claim_assistant_pending_action_for_current_user(v_id);
 select appointment_id into v_result from public.execute_claimed_assistant_pending_action_for_current_user(v_id);
 return v_result;
end; $$;
create function pg_temp.qa_create_args(p_patch jsonb default '{}') returns jsonb language sql as $$
 select jsonb_build_object('patient_id',pg_temp.qid('patient1'),'professional_clinic_member_id',pg_temp.qid('memberdoctorA'),'local_date','2030-01-08','local_time','10:00','duration_minutes',30)||p_patch;
$$;
set local role authenticated; select set_config('request.jwt.claim.sub',pg_temp.qid('owner')::text,true);
insert into qa_actions values ('newAppointment',pg_temp.qa_execute(pg_temp.qa_create_args()));
select extensions.throws_ok($t$select pg_temp.qa_execute(pg_temp.qa_create_args())$t$,'23P01',null,'Canonical conflict still denied');
select extensions.throws_ok($t$select pg_temp.qa_execute(pg_temp.qa_create_args('{"local_time":"18:00"}'))$t$,'23P01',null,'Canonical outside availability denied');
