select extensions.throws_ok($t$select pg_temp.qa_execute(pg_temp.qa_create_args('{"local_date":null}'))$t$,'22023',null,'Missing scheduling data denied');
select extensions.throws_ok($t$select pg_temp.qa_execute(jsonb_build_object('appointment_id',(select id from qa_actions where name='newAppointment'),'expected_status','confirmed'),'reschedule_appointment')$t$,'22023',null,'Reschedule requires validated local scheduling data');
select extensions.throws_ok($t$select pg_temp.qa_execute(jsonb_build_object('appointment_id',(select id from qa_actions where name='newAppointment'),'expected_status','confirmed'),'cancel_appointment')$t$,'40001',null,'Expected status contract preserved');
select extensions.throws_ok($t$select pg_temp.qa_execute(jsonb_build_object('appointment_id',(select id from qa_actions where name='newAppointment')),'cancel_appointment')$t$,'22023',null,'Lifecycle expected status cannot be bypassed by direct pending payload');
